  function installModalityPicker(){const f=$('#new-class-form'),select=f.elements.type;select.parentElement.outerHTML='<div class="field modality-picker"><label for="modality-query">Modalidade</label><input type="hidden" name="type"><input class="input" id="modality-query" role="combobox" aria-label="Modalidade" aria-autocomplete="list" aria-expanded="false" aria-controls="modality-options" autocomplete="off"><div id="modality-options" class="modality-options" role="listbox" hidden></div><p id="modality-summary" class="subtle">Escolha uma modalidade.</p></div>';f.dataset.modalityId='';$('#modality-query').addEventListener('input',e=>{f.elements.type.value='';f.dataset.modalityId='';modalityChoices(e.target.value)});$('#modality-query').addEventListener('click',()=>modalityChoices());$('#modality-query').addEventListener('keydown',e=>{const list=$('#modality-options'),items=[...list.querySelectorAll('[role="option"]')];if(e.key==='Escape'&&!list.hidden){e.preventDefault();e.stopPropagation();list.hidden=true;e.target.setAttribute('aria-expanded','false')}if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();if(list.hidden)modalityChoices(e.target.value);const options=[...list.querySelectorAll('[role="option"]')];if(!options.length)return;modalityIndex=(modalityIndex+(e.key==='ArrowDown'?1:-1)+options.length)%options.length;options.forEach((o,i)=>o.setAttribute('aria-selected',String(i===modalityIndex)));e.target.setAttribute('aria-activedescendant',options[modalityIndex].id)}if(e.key==='Enter'&&!list.hidden){e.preventDefault();if(items[modalityIndex])chooseModality(items[modalityIndex].dataset.pickModality)}if(e.key==='Tab'){list.hidden=true;e.target.setAttribute('aria-expanded','false')}})}
