  function loadRoute(r){state.filters={};for(const key of pageKeys[r.page]||[]){const value=r.query.get(key);if(!value)continue;if(['client','calClient','payClient','installmentClient','dashboardClient'].includes(key)&&!lookup(clients,value))continue;if(/Date$/.test(key)&&!validDate(value))continue;if(/Status$|^status$/.test(key)&&['dashboard','agenda','aulas'].includes(r.page)&&!['planned','done','cancelled'].includes(value))continue;if(key==='finance'&&!['due','paid','partial','pending','trial'].includes(value))continue;if(key==='financeScope'&&value!=='class')continue;if(key==='result'&&value!=='waiting')continue;if(key==='includeVoidedClasses'&&value!=='yes')continue;if(key==='recurrence'&&!['yes','no'].includes(value))continue;state.filters[key]=value}if(r.page==='agenda'){state.date=validDate(r.query.get('date'))?r.query.get('date'):TODAY;state.view=['dia','semana','mes','lista'].includes(r.query.get('view'))?r.query.get('view'):(matchMedia('(max-width:760px)').matches?'dia':'semana');state.manualView=r.query.has('view')}}
