  function timeEnd(a){const [h,m]=a.time.split(':').map(Number),n=h*60+m+a.duration;return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
  function newClass(date=state.date,time='09:00'){modal(modalHeader('Nova aula','Planeje uma aula avulsa ou uma série de ocorrências.')+`<form id="new-class-form"><div class="form-grid"><label class="field">Modalidade<select class="select" name="type" required><option value="">Selecione</option><option>Equitação básica</option><option>Salto</option><option>Adestramento</option><option>Experimental</option></select></label><label class="field">Instrutor<select class="select" name="instructor" required><option value="">Selecione</option>${team.filter(t=>t.role.startsWith('Instrutor')).map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></label><label class="field">Data inicial<input class="input" name="date" type="date" value="${date}" required></label><label class="field">Horário<input class="input" name="time" type="time" value="${time}" required></label><label class="field">Duração<select class="select" name="duration"><option value="45">45 minutos</option><option value="60" selected>60 minutos</option><option value="90">90 minutos</option></select></label><label class="field">Cavalo<select class="select" name="horse" required><option value="">Selecione</option>${horses.filter(h=>h.status!=='Em descanso').map(h=>`<option value="${h.id}">${esc(h.name)}</option>`).join('')}</select></label></div><div class="form-divider">PARTICIPANTES</div><div class="check-list">${clients.filter(c=>c.status!=='Inativo').map(c=>`<label class="check-line"><input type="checkbox" name="clients" value="${c.id}"> ${esc(c.name)}</label>`).join('')}</div><div class="form-divider">REPETIÇÃO</div><div class="form-grid"><label class="field">Frequência<select class="select" name="repeat"><option value="none">Não se repete</option><option value="weekly">Semanal</option><option value="custom">Personalizada</option></select></label><label class="field repeat-only" hidden>Até quando<input class="input" type="date" name="until" value="${addDays(date,28)}"></label><label class="field repeat-custom" hidden>Intervalo<select class="select" name="interval"><option value="2">A cada 2 semanas</option><option value="3">A cada 3 semanas</option><option value="4">A cada 4 semanas</option></select></label></div><div class="preview" id="date-preview">Uma ocorrência em ${fmtDate(date)}.</div><p class="subtle" style="margin-top:11px">Dono · simulação local. Preços fictícios por tipo são copiados por participante; uma série não registra conclusão nem cobrança como paga.</p><div class="dialog-actions"><button class="button" type="button" data-close>Cancelar</button><button class="button primary" type="submit">Planejar aula</button></div></form>`,true);installModalityPicker();installRecurrenceForm();updatePreview()}
  function recurrenceDates(f){return globalThis.EcobellaRecurrence.dates({start:f.elements.date.value,end:f.elements.repeat.value==='none'?f.elements.date.value:f.elements.until.value,cadence:f.elements.repeat.value,weekdays:[...f.querySelectorAll('[name="weekdays"]:checked')].map(el=>Number(el.value)),dayOfMonth:Number(f.elements.dayOfMonth.value)})}
  function updatePreview(){const f=$('#new-class-form');if(!f||f.dataset.editId)return;const repeat=f.elements.repeat.value;$('.repeat-only',f).hidden=repeat==='none';$('.repeat-days',f).hidden=repeat==='none'||repeat==='monthly';$('.repeat-month',f).hidden=repeat!=='monthly';const dates=recurrenceDates(f);$('#date-preview').textContent=dates.length?`${dates.length} ocorrência(s): ${dates.slice(0,8).map(d=>fmtDate(d,{day:'numeric',month:'short'})).join(' · ')}${dates.length>8?' · …':''}`:'Confira período, dias da semana e limite de 52 ocorrências.'}
  function installRecurrenceForm(){const f=$('#new-class-form');f.elements.repeat.innerHTML='<option value="none">Não se repete</option><option value="weekly">Semanal</option><option value="twice_weekly">Duas vezes por semana</option><option value="monthly">Mensal</option><option value="custom">Dias personalizados</option>';$('.repeat-custom',f).remove();$('.repeat-only',f).insertAdjacentHTML('afterend',`<fieldset class="repeat-days full"><legend>Dias da semana</legend>${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map((d,i)=>`<label><input type="checkbox" name="weekdays" value="${i}" ${new Date(f.elements.date.value+'T12:00:00').getDay()===i?'checked':''}>${d}</label>`).join('')}</fieldset><label class="field repeat-month">Dia do mês<input class="input" name="dayOfMonth" type="number" min="1" max="31" value="${Number(f.elements.date.value.slice(-2))}"></label>`);f.elements.horse.required=false;f.elements.horse.innerHTML=options(horses.map(h=>[h.id,`${h.name} · ${h.status}${h.restriction?' · '+h.restriction:''}`]),'','Informar na execução');$('#modality-query').insertAdjacentHTML('afterend','<label class="check-line"><input type="checkbox" name="trial">Aula experimental gratuita (um participante)</label><p class="subtle" id="trial-status">Benefício por CPF e modalidade; requer CPF preenchido.</p>');if(role()==='administrative'){f.elements.repeat.value='weekly';f.elements.repeat.querySelector('[value="none"]').remove()}data.modalities.filter(m=>m.name==='Experimental').forEach(m=>m.active=false)}
  function trialState(clientId,type){const client=lookup(clients,clientId);if(!client?.cpf)return 'CPF não informado';const m=data.modalities.find(m=>m.name===type);const prior=allClasses.find(a=>a.trial&&(a.modalityId?m?.id===a.modalityId:a.type===type)&&(a.clientIds.includes(clientId)||Object.values(a.trialCpfs||{}).includes(client.cpf))&&(a.status!=='cancelled'||a.trialConsumed));return prior?(prior.status==='done'||prior.trialConsumed?'Consumida':'Reservada'):'Disponível'}
  function editClass(id){if(!editRecords())return;const a=lookup(data.classes,id);if(!a||a.status!=='planned')return;newClass(a.date,a.time);const f=$('#new-class-form');f.dataset.editId=id;f.elements.instructor.value=a.instructor;f.elements.horse.value=a.horse||'';f.elements.trial.checked=!!a.trial;const m=data.modalities.find(m=>m.id===a.modalityId||m.name===a.type);if(m)chooseModality(m.id);f.elements.duration.value=String(a.duration);f.querySelectorAll('[name="clients"]').forEach(el=>el.checked=a.clientIds.includes(el.value));$('h2',$('#detail-dialog')).textContent='Editar aula';$('button[type="submit"]',f).textContent='Revisar alterações';f.elements.repeat.value='none';f.elements.repeat.closest('label').hidden=true;$('.repeat-only',f).hidden=true;$('.repeat-days',f).hidden=true;$('.repeat-month',f).hidden=true;$('#date-preview').textContent='A prévia do alcance aparecerá antes de confirmar.';$('#modality-summary').insertAdjacentHTML('afterend',`<p class="subtle">Cobranças existentes: ${a.clientIds.map(id=>`${esc(clientName(id))}: ${fmtMoney(a.charges[id])}`).join(' · ')}. Alterar padrão não recalcula esta aula.</p>`)}
  let pendingClassEdit=null;
